Below is a JavaScript class `UserManager` with implemented methods to manage a collection of user objects. The class includes proper validation for email format and age, along with error handling for invalid operations.

```javascript
class UserManager {
  constructor() {
    this.users = [];
    this.nextId = 1;
  }

  _isValidEmail(email) {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    return emailRegex.test(email);
  }

  _isValidAge(age) {
    return typeof age === 'number' && age > 0;
  }

  addUser(user) {
    if (typeof user.name !== 'string' || user.name.trim() === '') {
      throw new Error('User must have a valid name.');
    }

    if (!this._isValidEmail(user.email)) {
      throw new Error('Invalid email format.');
    }

    if (!this._isValidAge(user.age)) {
      throw new Error('Age must be a positive number.');
    }

    const newUser = { ...user, id: this.nextId++ };
    this.users.push(newUser);
    return newUser;
  }

  getUserById(id) {
    const user = this.users.find(u => u.id === id);
    if (!user) {
      throw new Error('User not found.');
    }
    return user;
  }

  updateUser(id, updates) {
    const userIndex = this.users.findIndex(u => u.id === id);
    if (userIndex === -1) {
      throw new Error('User not found.');
    }

    const updatedUser = { ...this.users[userIndex], ...updates };

    if ('name' in updates && (typeof updates.name !== 'string' || updates.name.trim() === '')) {
      throw new Error('Invalid user name.');
    }

    if ('email' in updates && !this._isValidEmail(updates.email)) {
      throw new Error('Invalid email format.');
    }

    if ('age' in updates && !this._isValidAge(updates.age)) {
      throw new Error('Age must be a positive number.');
    }

    this.users[userIndex] = updatedUser;
    return updatedUser;
  }

  deleteUser(id) {
    const userIndex = this.users.findIndex(u => u.id === id);
    if (userIndex === -1) {
      throw new Error('User not found.');
    }
    return this.users.splice(userIndex, 1)[0];
  }

  getAllUsers() {
    return this.users;
  }
}

// Example usage:
try {
  const userManager = new UserManager();
  userManager.addUser({ name: 'John Doe', email: 'john.doe@example.com', age: 25 });
  console.log(userManager.getAllUsers());
  const user = userManager.getUserById(1);
  console.log(user);
  userManager.updateUser(1, { name: 'Johnny Doe', age: 26 });
  console.log(userManager.getAllUsers());
  userManager.deleteUser(1);
  console.log(userManager.getAllUsers());
} catch (error) {
  console.error(error.message);
}
```

